<script setup lang="ts">import {ref,reactive,onMounted} from 'vue';import {go} from '../router';import {policies} from '../stores/policies';import {batches} from '../stores/batches';import {runs} from '../stores/runs';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {money} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),batch=ref('demo-batch'),p=reactive({amount_tolerance:0,max_days:7,require_reference:true,date_weight:1,reference_weight:20,reject_cost:40,max_candidates:16,max_group_size:4,max_group_amount:2000000});const {error,busy,act}=useTask();onMounted(()=>Promise.all([policies.load(),batches.load()]));function submit(){act(async()=>{await policies.create({name:name.value,batch_id:batch.value,...p});name.value=''})}function execute(id:string){act(async()=>{const r=await runs.create({policy_id:id});go('/results?run='+r.id)})}</script><template><PageHeading index="03 / 匹配口径" title="容差、拒配与搜索范围，要在运行前写明。" note="往来方和币种为硬约束。分数只用于候选排序，不是金额。参考引用可硬约束或软罚分；默认必须相同。"/><Notice :message="error"/><div class="two-col"><section><article v-for="r in policies.items.value" :key="r.id" class="policy-row"><p class="eyebrow">MATCHING POLICY</p><h2>{{r.name}}</h2><dl><div><dt>金额容差</dt><dd>{{r.amount_tolerance}}分</dd></div><div><dt>日期距离</dt><dd>{{r.max_days}}天</dd></div><div><dt>单侧拒配分</dt><dd>{{r.reject_cost}}</dd></div></dl><p>引用{{r.require_reference?'严格相同':'软成本'}} · 合并最多{{r.max_group_size}}项 / {{r.max_candidates}}个候选 / {{money(r.max_group_amount)}}元</p><button v-if="canWrite()" :disabled="busy" @click="execute(r.id)">执行两阶段勾稽 →</button></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>建立匹配口径</h2><label>口径名称<input v-model="name" required minlength="2"></label><label>对账批次<select v-model="batch"><option v-for="r in batches.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><div class="form-pair"><label>金额容差（分）<input type="number" v-model.number="p.amount_tolerance" min="0" max="10000" step="1"></label><label>日期距离（天）<input type="number" v-model.number="p.max_days" min="0" max="90" step="1"></label></div><label class="checkbox-label"><input type="checkbox" v-model="p.require_reference">引用必须相同且非空</label><div class="form-pair"><label>每天日期分<input type="number" v-model.number="p.date_weight" min="0" max="1000" step="any"></label><label>引用不同分<input type="number" v-model.number="p.reference_weight" min="0" max="10000" step="any"></label></div><label>单侧拒配分<input type="number" v-model.number="p.reject_cost" min=".001" max="10000" step="any"></label><div class="form-pair"><label>候选上限<input type="number" v-model.number="p.max_candidates" min="2" max="20"></label><label>合并组上限<input type="number" v-model.number="p.max_group_size" min="2" max="6"></label></div><label>合并金额上限（分）<input type="number" v-model.number="p.max_group_amount" min="1" max="10000000" step="1"></label><button :disabled="busy">保存匹配口径</button></form></div></template>
